mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g1-3/bot.mjs';

const CHI = 'America/Chicago';
const OK_BODY = 'Sale today! Reply STOP to opt out.';
const to = (over = {}) => ({ phone: '+13125550142', timeZone: CHI, marketingConsent: true, optedOutAt: null, ...over });
const mkt = (over = {}, toOver = {}) => ({ kind: 'marketing', body: OK_BODY, to: to(toOver), ...over });
const tx = (over = {}, toOver = {}) => ({ kind: 'transactional', body: 'Your code is 123456', to: to(toOver), ...over });
// Chicago 2026-10-22 local times -> UTC (CDT = UTC-5 until Nov 1)
const at = (h, m = 0) => new Date(Date.UTC(2026, 9, 22, h + 5, m));

const cases = [
  ['marketing 10:00 local ok', mkt(), at(10), { allowed: true, reason: null }],
  ['marketing 08:00 local ok (boundary)', mkt(), at(8), { allowed: true, reason: null }],
  ['marketing 07:59 local quiet', mkt(), at(7, 59), { allowed: false, reason: 'marketing_quiet_hours' }],
  ['marketing 20:59 local ok', mkt(), at(20, 59), { allowed: true, reason: null }],
  ['marketing 21:00 local quiet', mkt(), at(21), { allowed: false, reason: 'marketing_quiet_hours' }],
  ['marketing no consent', mkt({}, { marketingConsent: false }), at(10), { allowed: false, reason: 'no_marketing_consent' }],
  ['marketing consent missing', mkt({}, { marketingConsent: undefined }), at(10), { allowed: false, reason: 'no_marketing_consent' }],
  ['marketing no STOP wording', mkt({ body: 'Sale today!' }), at(10), { allowed: false, reason: 'marketing_missing_opt_out_instructions' }],
  ['marketing opted out', mkt({}, { optedOutAt: '2026-10-01T12:00:00Z' }), at(10), { allowed: false, reason: 'opted_out' }],
  ['transactional opted out', tx({}, { optedOutAt: '2026-10-01T12:00:00Z' }), at(10), { allowed: false, reason: 'opted_out' }],
  ['transactional bad optedOutAt', tx({}, { optedOutAt: 'garbage' }), at(10), { allowed: false, reason: 'invalid_opt_out_timestamp' }],
  ['transactional 03:00 local ok', tx(), at(3), { allowed: true, reason: null }],
  ['transactional no consent ok', tx({}, { marketingConsent: false }), at(10), { allowed: true, reason: null }],
  ['transactional no STOP wording ok', tx({ body: 'Code 1' }), at(10), { allowed: true, reason: null }],
  ['bad kind', { ...mkt(), kind: 'promo' }, at(10), { allowed: false, reason: 'invalid_kind' }],
  ['bad phone (not NANP)', mkt({}, { phone: '+12125550142' }), at(10), { allowed: false, reason: 'invalid_phone' }],
  ['bad phone (not E.164)', mkt({}, { phone: '3125550142' }), at(10), { allowed: false, reason: 'invalid_phone' }],
  ['empty body', mkt({ body: '   ' }), at(10), { allowed: false, reason: 'empty_body' }],
  ['bad time zone', mkt({}, { timeZone: 'Mars/Olympus' }), at(10), { allowed: false, reason: 'invalid_time_zone' }],
  ['missing time zone', mkt({}, { timeZone: undefined }), at(10), { allowed: false, reason: 'invalid_time_zone' }],
  ['invalid now', mkt(), new Date('nope'), { allowed: false, reason: 'invalid_time' }],
  ['now not a Date', mkt(), '2026-10-22', { allowed: false, reason: 'invalid_time' }],
  ['null message', null, at(10), { allowed: false, reason: 'invalid_message' }],
  ['missing recipient', { kind: 'marketing', body: OK_BODY }, at(10), { allowed: false, reason: 'invalid_recipient' }],
];

let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = checkSms(msg, now);
  try { assert.deepEqual(got, want); console.log('ok  ', name); }
  catch { fail++; console.log('FAIL', name, JSON.stringify(got), 'want', JSON.stringify(want)); }
}

// Same instant, two zones: Chicago 10:00 is 15:00 UTC, Tokyo 15:00 is 06:00 UTC next... use Honolulu to show zone matters per customer
const sameInstant = new Date('2026-10-22T15:00:00Z'); // 10:00 Chicago, 05:00 Honolulu
assert.equal(checkSms(mkt({}, { timeZone: 'Pacific/Honolulu' }), sameInstant).reason, 'marketing_quiet_hours');
assert.equal(checkSms(mkt({}, { timeZone: CHI }), sameInstant).allowed, true);
console.log('ok   per-customer zone decides quiet hours');

// Distinct codes for distinct rules
const codes = cases.map(c => c[3].reason).filter(Boolean);
assert.equal(new Set(codes).size, new Set(codes).size);
console.log(fail ? `${fail} FAILED` : `all ${cases.length} cases passed`);
process.exitCode = fail ? 1 : 0;
EOF
cd /tmp/bot-check && for tz in UTC Asia/Tokyo America/Los_Angeles Pacific/Kiritimati; do echo "== server TZ=$tz"; TZ=$tz node check.mjs | tail -3; done; echo "== full run"; TZ=Asia/Tokyo node check.mjs
